const item = $input.item.json;

// Wird nur erreicht, wenn teamPerformance.dataAvailable === false (Gate
// "Teamdiagnose: Datenverfuegbarkeit pruefen" davor). Es gibt in diesem Fall
// nichts, was ein LLM interpretieren koennte - die Ollama-Chain wird bewusst
// NICHT aufgerufen, das Fehlen der Datengrundlage wird stattdessen selbst zum
// (weiterhin schema-gueltigen) Ergebnis. Siehe n8n/README.md.
const teamDiagnosis = {
  simulated: false,
  dataAvailable: false,
  diagnosisCategory: 'no_data',
  evidence: [
    `Keine importierten Analytics-Daten fuer '${item.club}' vorhanden (Data Table 'football_scouting_raw') - es werden keine Ersatzwerte erfunden.`
  ],
  leagueComparisonAvailable: false,
  leagueComparison: `Ohne Datengrundlage ist kein Ligavergleich fuer '${item.club}' moeglich.`,
  hypotheses: [
    'Ohne Datengrundlage kann keine belastbare Hypothese zur sportlichen Situation abgeleitet werden.'
  ],
  counterHypotheses: [],
  mainProblem: `Fuer '${item.club}' liegen keine CSV-Analytics-Daten vor; auf dieser Datengrundlage ist keine Diagnose moeglich.`,
  uncertainties: [
    'Diese Aussage stammt aus dem CSV-Analytics-Adapter (Data Table football_scouting_raw), nicht aus einer echten Qlik-Analyse oder Websuche.',
    'Ohne Datengrundlage konnte kein LLM zur Interpretation herangezogen werden.'
  ]
};

return [{ json: { ...item, teamDiagnosis } }];

const item = $input.item.json;
const perf = item.teamPerformance;
const matches = item.teamMatches;

// Bereitet die vom LLM zu interpretierenden GEGEBENEN FAKTEN vor: dieselbe
// deterministische Faktenextraktion aus teamPerformance/teamMatches wie zuvor
// (CSV-Analytics-Adapter, siehe n8n/README.md), aber OHNE die Interpretation
// (Hypothesen, Hauptproblem, Ligavergleich, Gegenhypothesen) - die uebernimmt
// jetzt "Teamdiagnose LLM". Diese Trennung stellt sicher, dass die Evidenz
// ausschliesslich aus echten Kennzahlen besteht (nichts erfunden) und das LLM
// erkennbar nur interpretiert statt selbst Zahlen zu erzeugen.
const recentResults = (matches && Array.isArray(matches.matches))
  ? matches.matches.map((m) => `${m.result} ${m.goalsFor}:${m.goalsAgainst} vs. ${m.opponent} (${m.date})`)
  : [];

const teamDiagnosisEvidence = [
  `Bilanz der letzten ${perf.matchesAnalyzed} Pflichtspiele: ${perf.wins}S/${perf.draws}U/${perf.losses}N, Tore ${perf.goalsFor}:${perf.goalsAgainst}, Punkte ${perf.points} (CSV-Analytics-Adapter, Data Table football_scouting_raw).`,
  `Form (neuestes Spiel zuerst): ${perf.form.join('-')}.`,
  `Punkteschnitt der letzten ${perf.matchesAnalyzed} Spiele: ${(perf.points / perf.matchesAnalyzed).toFixed(2)} pro Spiel.`,
  `Durchschnittliche Tore pro Spiel: ${perf.avgGoalsFor} erzielt, ${perf.avgGoalsAgainst} kassiert (Tordifferenz ${perf.goalDifference}).`,
  ...recentResults
];

return [{ json: { ...item, teamDiagnosisEvidence } }];

parameters.text:
=Verein: {{ $json.club }}
Zielsetzung des Auftrags: {{ $json.objective }}
Zusaetzlicher Kontext: {{ $json.additionalContext || '(keiner)' }}

Gegebene Fakten aus dem CSV-Analytics-Adapter (bereits real berechnet - NICHT erfinden, nur interpretieren):
{{ $json.teamDiagnosisEvidence.join('\n') }}

Rohkennzahlen: avgGoalsFor={{ $json.teamPerformance.avgGoalsFor }}, avgGoalsAgainst={{ $json.teamPerformance.avgGoalsAgainst }}, Punkte={{ $json.teamPerformance.points }} aus {{ $json.teamPerformance.matchesAnalyzed }} Spielen.

Interpretiere ausschliesslich auf Basis dieser Fakten (keine erfundenen Zahlen, keine externen Annahmen). Ordne die Lage genau einer von drei Kategorien zu: 'defensive' (mehr Gegentore als eigene Tore / auffaellige Anfaelligkeit), 'offensive' (zu wenige eigene Tore trotz stabilerer Defensive) oder 'neutral' (kein eindeutiger struktureller Schwerpunkt). Liefere zusaetzlich einen Ligavergleich: Dir liegen ausschliesslich die Kennzahlen von '{{ $json.club }}' vor, KEINE Liga-Durchschnittswerte und KEINE Kennzahlen anderer Bundesliga-Vereine. Erfinde deshalb KEINE Platzierung, KEINEN Liga-Durchschnitt und KEINEN Vergleich zu konkreten anderen Vereinen - benenne in 'leagueComparison' stattdessen explizit, dass auf dieser Datengrundlage kein belastbarer Vergleich zur Bundesliga-Konkurrenz moeglich ist, und was dafuer zusaetzlich vorliegen muesste (z. B. Liga-weite Kennzahlen aller Vereine). Liefere ausserdem Hypothesen zur Ursache, Gegenhypothesen (plausible alternative Erklaerungen, die denselben Fakten ebenfalls nicht widersprechen), das Hauptproblem in einem Satz sowie Unsicherheiten (was diese Diagnose NICHT abdeckt, z. B. fehlende erwartbare Tore/xG, Gegnerstaerke, Verletzungen, kein Kontext zu anderen Vereinen).

